import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine().trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); StringTokenizer st = new StringTokenizer(br.readLine()); int totalEvenPossible = 0; for (int i = 0; i < 2 * n; i++) { int val = Integer.parseInt(st.nextToken()); if (val % 2 == 0) { int count = 0; while (val > 0 && val % 2 == 0) { val /= 2; count++; } totalEvenPossible += count; } } if (totalEvenPossible >= n) { System.out.println("YES"); } else { System.out.println("NO"); } } } }